/* This program reads two numbers from standard input and performs a calculation based on their values. */

  function   Main (  input  )   {

    // Declare variables to store the two numbers.
    var   a  ,  b  ;

    // Parse the first number from the input string.
    a   =   Number (  input  .  split (  '\n'  )  [  0  ]  .  split (  ' '  )  [  0  ]  ) ;

    // Parse the second number from the input string.
    b   =   Number (  input  .  split (  '\n'  )  [  0  ]  .  split (  ' '  )  [  1  ]  ) ;


    // Check conditions to determine the output.
    if  (  a  ===  b  )   {  /* If the two numbers are exactly equal, the result is 0. */

        console  .  log  (  0  )  ;

    }  else   if  (  (  a  +  b  )  %  2  ===  0  )   {  // If the sum of the two numbers is an even number...

        console  .  log  (  (  a  +  b  )  /  2  )  ; // Output half of their sum.

    }  else   {  // If none of the above conditions are met, it's impossible.

        console  .  log  (  'IMPOSSIBLE'  )  ;

    }

}


